(() => {
  const page=new URLSearchParams(location.search).get('page');
  if(!['geography','magic','people'].includes(page))return;
  const root=document.querySelector('.page-inner');
  const data=window.CURTAIN_CONTENT;
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const panel=document.createElement('section');panel.className='atlas-panel atlas-'+page;
  const link=(id,label)=>`<a class="atlas-read" href="?article=${id}">${label} <span>↗</span></a>`;
  const svgOpen='<svg viewBox="0 0 800 520" preserveAspectRatio="none" aria-hidden="true" class="atlas-drawing">';
  const ring=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="currentColor"/>`;
  if(page==='geography'){
    const positions=[[50,48],[23,25],[77,25],[23,75],[77,75]];
    const ids=['camoria','eisen','northlands','esperanza','enchantevis'];
    const economy=['高级巫师与咒语填充','精密工艺与造物制造','冻土矿脉与生物制品','港口、海洋与蕴法石','森林、草药与魔药'];
    panel.innerHTML=`<div class="atlas-heading"><div><p class="atlas-eyebrow">地理观测 · 方位图</p><h2>五大陆之间</h2></div><p>选择一处方位，阅读它的地方传统。</p></div><div class="atlas-body"><div class="atlas-stage geo-stage">${svgOpen}<defs><radialGradient id="sea"><stop stop-color="#355c54"/><stop offset="1" stop-color="#102c2d"/></radialGradient></defs><rect width="800" height="520" fill="url(#sea)"/><g class="survey-lines">${[90,180,270,360].map(r=>`<ellipse cx="400" cy="250" rx="${r}" ry="${r*.58}"/>`).join('')}<path d="M40 260H760 M400 30V490 M100 60L700 460 M700 60L100 460"/>${Array.from({length:21},(_,i)=>`<path d="M${40+i*36} 36v${i%5===0?12:5} M${40+i*36} 484v-${i%5===0?12:5}"/>`).join('')}</g><g class="compass"><path d="M400 59l-6 15h12z"/><text x="400" y="50" text-anchor="middle">N</text></g></svg>${data.regions.map((r,i)=>`<button class="atlas-pin" data-place="${i}" style="left:${positions[i][0]}%;top:${positions[i][1]}%" aria-pressed="${i===0}"><span class="pin-diamond"></span><small>${escape(r.direction)}</small><strong>${escape(r.name)}</strong></button>`).join('')}<span class="atlas-caption">方位与联系示意，不表示海岸线或实际距离</span></div><div class="atlas-note" aria-live="polite"></div></div>`;
    const note=panel.querySelector('.atlas-note');
    const render=i=>{const r=data.regions[i];panel.querySelectorAll('.atlas-pin').forEach((b,j)=>b.setAttribute('aria-pressed',String(j===i)));note.innerHTML=`<span class="atlas-index">${escape(r.direction)}大陆</span><h3>${escape(r.name)}</h3><p>${escape(r.description)}</p><dl><dt>经济与工艺</dt><dd>${economy[i]}</dd><dt>魔法传统</dt><dd>${escape(r.focus)}</dd></dl>${link(ids[i],'阅读地方志')}`;};
    panel.querySelectorAll('[data-place]').forEach(b=>b.addEventListener('click',()=>render(+b.dataset.place)));render(0);
    // The older overview remains a text alternative, without repeating two selection panels.
    const old=root.querySelector('.regions');if(old){old.previousElementSibling?.remove();old.previousElementSibling?.remove();old.nextElementSibling?.remove();old.remove();}
  }
  if(page==='magic'){
    const stages=[['起势','回路与自然共鸣','魔法回路与周围环境中的自然力量达成共鸣，将力量引入体内。施法从建立联系开始。'],['塑形','为力量赋予结构','引入的力量经由回路形成适合预期效果的结构。火焰、冰霜与防御需要不同的形态；结构不稳时可能反噬。'],['稳定','咒文细化施法意图','咒文稳定并进一步雕琢已经成形的魔力，使其更接近施法者的意图。这一步依赖对具体咒语的理解。'],['导出','媒介完成最终定型','施法媒介将力量精准导出，同时辅助稳定和最终塑形。工具与使用者长期形成的熟悉程度也会影响效果。']];
    panel.innerHTML=`<div class="atlas-heading"><div><p class="atlas-eyebrow">施法研究 · 过程图解</p><h2>一次咒语的形成</h2></div><p>选择阶段，观察力量从共鸣到释放的过程。</p></div><div class="atlas-body"><div class="atlas-stage casting-stage">${svgOpen}<defs><radialGradient id="field"><stop stop-color="#55766a" stop-opacity=".6"/><stop offset="1" stop-color="#112d2c" stop-opacity="0"/></radialGradient></defs><rect width="800" height="520" fill="#102c2d"/><circle cx="400" cy="255" r="230" fill="url(#field)"/><g class="casting-orbits">${ring(400,255,190)}${ring(400,255,174)}${ring(400,255,116)}${Array.from({length:48},(_,i)=>{const a=i*Math.PI/24;return `<path d="M${400+Math.cos(a)*181} ${255+Math.sin(a)*181} L${400+Math.cos(a)*(i%4===0?166:175)} ${255+Math.sin(a)*(i%4===0?166:175)}"/>`;}).join('')}</g><g class="casting-track"><path d="M120 255C220 95 315 410 400 255S580 95 680 255"/><path d="M120 255C220 410 315 95 400 255S580 410 680 255"/></g>${[160,320,480,640].map((x,i)=>`<g class="casting-node" data-phase="${i}"><circle cx="${x}" cy="255" r="${i===3?23:18}"/><circle cx="${x}" cy="255" r="${i===3?34:29}"/><text x="${x}" y="326" text-anchor="middle">${stages[i][0]}</text></g>`).join('')}<circle class="cast-particle" cx="160" cy="255" r="5"/></svg><span class="atlas-caption">概念图解：描述施法阶段，不代表实际回路形态</span></div><div class="atlas-note" aria-live="polite"></div></div><div class="phase-controls" role="group" aria-label="选择施法阶段">${stages.map((s,i)=>`<button data-step="${i}" aria-pressed="${i===0}"><small>0${i+1}</small>${s[0]}</button>`).join('')}<button class="cast-replay">演示一次 ↻</button></div>`;
    let timer=null;
    const render=i=>{panel.querySelectorAll('[data-step]').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));panel.querySelectorAll('[data-phase]').forEach((n,j)=>n.classList.toggle('active',j<=i));const s=stages[i];panel.querySelector('.atlas-note').innerHTML=`<span class="atlas-index">阶段 0${i+1} / 04</span><h3>${s[0]}</h3><h4>${s[1]}</h4><p>${s[2]}</p>${link('casting-reference','阅读施法详论')}`;const dot=panel.querySelector('.cast-particle');if(window.gsap&&!matchMedia('(prefers-reduced-motion: reduce)').matches){gsap.to(dot,{attr:{cx:160+i*160},duration:.65,ease:'power2.inOut'});}else dot.setAttribute('cx',160+i*160);};
    panel.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>{clearInterval(timer);timer=null;panel.querySelector('.cast-replay').textContent='演示一次 ↻';render(+b.dataset.step)}));
    panel.querySelector('.cast-replay').addEventListener('click',()=>{clearInterval(timer);let i=0;render(i);panel.querySelector('.cast-replay').textContent='重新演示 ↻';timer=setInterval(()=>{if(++i===4){clearInterval(timer);timer=null;panel.querySelector('.cast-replay').textContent='演示一次 ↻';return;}render(i);},1600);});render(0);
    document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInterval(timer);timer=null;panel.querySelector('.cast-replay').textContent='演示一次 ↻';}});
  }
  if(page==='people'){
    const people=[['庭代尔','导师与领导者','tyndale-early',50,46],['厄尼西姆','首席 · 赛特斯族','ernicium-profile',20,20],['加利贝尔','次席 · 翼人族','galibel-profile',50,14],['普里多尼','第三席 · 质人族','pridony-profile',80,20],['赫法恩斯','第四席 · 半羊人族','huffines-profile',20,78],['塞浦路斯','第五席 · 星中人混血','cyprus-profile',50,85],['切西娅','第六席 · 月人族','chessia-profile',80,78]];
    panel.innerHTML=`<div class="atlas-heading"><div><p class="atlas-eyebrow">人物研究 · 关系索引</p><h2>相遇之后，成为家人</h2></div><p>从骑士团的公开关系进入人物档案。</p></div><div class="atlas-body"><div class="atlas-stage people-stage">${svgOpen}<rect width="800" height="520" fill="#102c2d"/><g class="relation-rings">${ring(400,250,185)}${ring(400,250,210)}</g><g class="relation-lines">${people.slice(1).map((p,i)=>`<path data-relation="${i+1}" d="M400 239 Q${(400+p[3]*8)/2} ${i<3?85:440} ${p[3]*8} ${p[4]*5.2}"/>`).join('')}</g></svg>${people.map((p,i)=>`<button data-person="${i}" class="person-node ${i===0?'person-center':''}" style="left:${p[3]}%;top:${p[4]}%" aria-pressed="${i===0}"><span>${p[0]}</span><small>${p[1]}</small></button>`).join('')}<span class="atlas-caption">关系示意：庭代尔与骑士团六席；不表示力量或亲疏排序</span></div><div class="atlas-note" aria-live="polite"></div></div>`;
    const render=i=>{const p=people[i];panel.querySelectorAll('[data-person]').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));panel.querySelectorAll('[data-relation]').forEach(n=>n.classList.toggle('active',+n.dataset.relation===i||i===0));const a=data.articles.find(a=>a.id===p[2]);panel.querySelector('.atlas-note').innerHTML=`<span class="atlas-index">${p[1]}</span><h3>${p[0]}</h3><p>${escape(a?.lead||'在共同生活与不同经历之间，理解一位历史人物。')}</p><p class="relation-label">${i===0?'庭代尔挑选并教导成员，既是领导者，也是共同生活中的导师。':'与庭代尔：导师与追随者。成员来自不同背景，席次之外也有各自的经历。'}</p>${link(p[2],'打开人物档案')}`;};
    panel.querySelectorAll('[data-person]').forEach(b=>b.addEventListener('click',()=>render(+b.dataset.person)));render(0);
  }
  const curator=root.querySelector('.curator-feature');if(curator)curator.after(panel);else root.prepend(panel);
})();
